-- A dump of a small loaded warehouse, for the GitHub Actions job and for
-- anyone who wants the tests to run without calling Coinbase.
--
-- Two products (BTC-USD, ETH-USD) at two timeframes (15m, 1h) over two days,
-- loaded by scripts/run_ingest.py on 2026-10-09 in two runs. Raw therefore
-- holds the duplicate copies the three-hour overlap re-fetch leaves behind,
-- and the run records show runs that found nothing to change, which is the
-- state after an ordinary daily load. The file holds data only. Apply it after
-- scripts/run_setup.py has created the schema and the empty marts, then
-- refresh the marts with scripts/run_dbt.py run. The seeded rows of
-- core.assets and core.timeframes are not repeated here; the two UPDATEs
-- below set the work list the data was loaded under. The identity columns
-- keep their original values, so the sequences are moved past them at the
-- end. Generated with pg_dump --data-only --inserts; the SET lines and
-- comments pg_dump adds were removed.
--
--   psql "$DATABASE_URL" -v ON_ERROR_STOP=1 -f tests/fixtures/warehouse_sample.sql

UPDATE core.timeframes SET is_active = true WHERE timeframe_code = '15m';
UPDATE core.assets SET is_active = false WHERE product_code NOT IN ('BTC-USD', 'ETH-USD');

SELECT pg_catalog.setval('raw.candles_raw_id_seq', 516, true);
SELECT pg_catalog.setval('raw.fetch_windows_fetch_id_seq', 8, true);
SELECT pg_catalog.setval('raw.ingest_runs_run_id_seq', 8, true);
